					<el-button  v-if="authKeys" type="success" icon="el-icon-circle-plus-outline" size="medium" @click="goToAdd()">新建</el-button>
					<el-button v-if="authKeys"  type="danger" icon="el-icon-delete" size="medium" @click="deleteUsers"
					 v-loading.fullscreen.lock="fullscreenLoading">删除</el-button>
					<el-button  v-if="authKeys" type="warning" icon="el-icon-document" size="medium" @click="showCopyDialog">批量复制权限</el-button>
					<el-button type="info" icon="el-icon-upload2" size="medium" @click="exportDataEvent">导出</el-button>
                  <!--  <el-button type="primary" icon="el-icon-printer" size="medium"  @click="dialogTableVisible = true">打印</el-button>-->
			 		<!-- <el-button type="primary" icon="el-icon-printer" size="medium"  @click="dayin" >打印2</el-button> -->
					<el-input style="margin-left:30px;width: 350px;" size="medium" placeholder="搜索姓名" v-model="searchFilter.name"
					 clearable  prefix-icon="el-icon-search">
					
					  <el-button slot="append" icon="el-icon-search"  size="medium" plain @click="handleSearch">搜索</el-button> 
					<!--    <el-button slot="append" icon="el-icon-error" size="medium" plain @click="clearFilter()">清空</el-button>  -->
