				<!-- 	 <el-input style="margin-left:10px;width: 150px;" size="medium" placeholder="搜索账号" v-model="searchFilter.account"
					 clearable></el-input> 
					 <el-autocomplete style="margin-left:10px;width: 80px;" v-model="searchFilter.disable" :fetch-suggestions="querySearch"
					 clearable placeholder="停用" size="medium"></el-autocomplete>  -->
				<!-- 	<el-button style="margin-left:10px;" type="primary" icon="el-icon-search" size="medium" plain @click="handleSearch">搜索</el-button> -->
					<!-- <el-button type="primary" icon="el-icon-close" size="medium" plain @click="clearFilter()"></el-button>  -->
				</div>
                 
				<vxe-table style="margin-top: 10px;" border stripe resizable highlight-hover-row highlight-current-row align="center"
				 :height="tableHeight" :loading="loading" row-id="id" :print-config="{}"  :data="tableData" ref="xTable1" id="dy1">
					<vxe-table-column type="checkbox" width="60"></vxe-table-column>
					<vxe-table-column  v-if="authKeys" title="操作" width="80"> <!-- v-if="authKeys.indexOf('超级管理员')>-1"-->
						<template v-slot="{ row }">
							<el-button type="warning" plain size="small" @click="goToEdit(row)">编辑</el-button>
						</template>
					</vxe-table-column>
					<vxe-table-column type="seq" width="60" title="序号"></vxe-table-column>

					<vxe-table-column field="id" title="id" :visible="false"></vxe-table-column>
					<vxe-table-column field="用户名" title="姓名"></vxe-table-column>
					<vxe-table-column field="角色" title="角色"></vxe-table-column>
					<vxe-table-column field="联系方式" title="电话"></vxe-table-column>
					<vxe-table-column field="照片" title="照片" :formatter="formatterTF"></vxe-table-column> 
					<vxe-table-column field="住址" title="住址"></vxe-table-column>
                   <!--  <vxe-table-column field="time" title="time">
					</vxe-table-column> -->
				</vxe-table>
				<vxe-pager :loading="loading" :current-page="tablePage.currentPage" :page-size="tablePage.pageSize" :total="tablePage.totalResult"
				 :layouts="['PrevPage', 'JumpNumber', 'NextPage', 'FullJump', 'Sizes', 'Total']" @page-change="handlePageChange">
				</vxe-pager> 
			
			<el-dialog  :visible.sync="dialogTableVisible"  width="65%" @opened="printEvent1">
			<div slot="title" class="dialog-footer" >
           <el-button @click="dialogTableVisible = false">取 消</el-button>
          <el-button type="primary" @click="printEvent1">打 印</el-button>
		  <!-- <div id="myPrint6">           
            <p>将当前渲染的<span style="color: #20f320">内容</span>打印出来，仅<span style="color: blue;font-size: 20px">打印</span>内联<span style="color: red">样式</span></p>
            <p>内容<span style="font-size: 30px;font-weight: 700">区域</span></p>
          </div> -->
           </div>
		   <div ref="print"  id="myPrint5"  media='print' style='font-family:\\5B8B\\4F53'>
            <div v-for="(item,index) in tableData"  :key="index"    v-show="isShow" >
				<div v-if="index%3 == 0"  ref="print2">
					<div style='width:60%;margin:0 auto;text-align: center;'>
			<h1 style='padding: 12px 0px 34px 0;' id="djmz">采购单</h1>
			<!-- <div style='float:right;    font-size: 14px;font-weight: 800;'>页码:{{(index+3)/3}}/{{Math.ceil(tableData.length/3)}}</div> -->
			</div> 
                 
				<table  border='0' style='width:100%;' id='printtable1'>					
					      	<tr height='30px;'>
					        <td style='text-align:left;'>入库单号：<span id=''>{{item.id}}</span></td>
					        <td style='text-align:center;'>单位名称：<span id=''>{{item.住址}}</span></td> 
					    </tr>                        
					    </table> 
				<table  border='1'  style='width:100%; display:inline-table;border-collapse: collapse;' id='printtable2'>
					    <tr height='40px;'>
							<td style='text-align:center;width:10%'>序号</td>
					        <td style='text-align:center;width:20%'>姓名</td>
					        <td style='text-align:center;width:20%'>联系方式</td> 
					        <td style='text-align:center;width:20%'>照片</td> 
					        <td style='text-align:center;width:30%'>住址</td> 
					    </tr>
					    <tr height='40px;' v-for="(ite,ind) in tableData.slice(index,index+3)" >
							<td style='text-align:center;'>{{ind}}</td>
					        <td style='text-align:center;'>{{ite.用户名}}</td>
					        <td style='text-align:center;'>{{ite.联系方式}}</td>
					        <td style='text-align:center;'>{{ite.照片}}</td>
					        <td style='text-align:center;'>{{ite.住址}}</td>
					    </tr>	
		         </table>
				 <table  border='0' style='width:100%;' id='printtable4' >		 							   
		  		   <tr height='30px;'>
					     <td style='text-align:left;'>页码:<span id=''>{{(index+3)/3}}/{{Math.ceil(tableData.length/3)}}</span></td>
					     <td style='text-align:center;'><span id=''></span></td>
					     <td style='text-align:right;'>金额合计(大写):</td> 
		                 <!-- <td style='text-align:left;'>&nbsp;<span id=''>{{setter.ToString(zje.toFixed(2))}}</span></td>  -->
					     <!-- <td style='text-align:center;'>￥:&nbsp;<span id=''>{{}}</span></td>  -->
			      </tr>	
		 		</table>  
				<table  border='0' style='width:100%;' id='printtable3'>
			          <tr height='30px;'>
					     <td style='text-align:left;'>制单：<span id=''>{{item.id}}</span></td>
					     <td style='text-align:center;'>保管员：<span id=''>{{item.用户名}}</span></td>
					     <td style='text-align:right;'>入库日期：<span id=''>{{item.照片}}</span></td> 
			      </tr>			      
			   </table> 
			   
          
				<div style='page-break-after:always;'></div>
			</div>
			</div> 
			</div>
			</el-dialog>
			</div>
			
          
			
			<div v-if="nowView===2">
				<UserEdit :passID="passID" :authKeys="authKeys" @goBack="goBack"></UserEdit>
			</div>

			<el-dialog title="批量授权" width="500px" :visible.sync="authCopy.dialogVisible">
				<el-form ref="authForm" :model="authCopy.form" :rules="authCopy.rules">
					<el-form-item prop="selectUserID" size="medium">
						<span>把</span>
						<el-select style="margin-left:10px ;margin-right:10px ;width: 180px;" v-model="authCopy.form.selectUserID"
						 clearable placeholder="请选择用户">
							<el-option v-for="item in authCopy.userOptions" :key="item.id" :label="item.用户名" :value="item.功能权限">
							</el-option>
						</el-select>
						<span>的权限，批量复制给当前勾选的用户</span>
					</el-form-item>
				</el-form>
				<div slot="footer">
					<el-button size="medium" @click="closeCopyDialog">取 消</el-button>
					<el-button type="primary" size="medium" @click="handleCopyAuth">确 定</el-button>
				</div>
			</el-dialog>

		</div>
	</d2-container>	
</template>

<script>
    import printJS from 'print-js'
    import { mapState, mapActions } from 'vuex'
	import UserEdit from './UserEdit.vue'
	import setter from '@/libs/setter.js'
	//import Print from './plugin/print/Print'
	import {
		GetMenuTreeOnAuth,
	} from '@api/sys.login.js'
    import {
		Query,
		Aud
	} from '@api/shuju.js'

	export default {
		name: 'UserInfo',
		components: {
			UserEdit,
		},
		data() {
			return {
				fullscreenLoading: false,
				nowView: 1, //当前视图：1是列表，2是编辑页面
				authKeys: false, //用户的权限数组
				tableHeight: 0, //表格高度
				tableData: [], //表内数据	相当于layuidata			
				loading: false, //是否显示加载中
				tablePage: { // 分页属性---
					currentPage: 1, //当前页 相当于layui的page
					pageSize: 10,  	//每页条数 相当于layui的limt
					totalResult: 0  //总页数   相当于count				
				},
				isShow:true,
				TFList: [{
						label: '是',
						value: true
					},
					{
						label: '否',
						value: false
					}
				],
				gnqx:[],
				uname:'',
				//搜索变量
				searchFilter: {
					name: '',
					//account: '',
					//disable: ''
				},
				disables: [{
					'value': '是'
				}, {
					'value': '否'
				}],

                 dialogTableVisible: false,

				passID: null,

				//批量复制权限
				authCopy: {
					dialogVisible: false,
					userOptions: [],
					form: {
						selectUserID: ''
					},
					rules: {
						selectUserID: [{
							required: true,
							message: '请选择用户',
							trigger: 'change'
						}]
					}
				},
              
			  
			}
		},
		created() {
			this.getAuthKeys()
			
		},
		mounted() {
			this.autoTableHeight()
		},
	
		methods: {

			//表格根据浏览器调整高度---
			autoTableHeight() {
				this.tableHeight = window.innerHeight - 235;
				window.onresize = () => {
					return (() => {
						this.tableHeight = window.innerHeight - 235;
					})();
				};
			},
               
			getAuthKeys() {
            let sj =   JSON.parse(window.localStorage.getItem('d2admin-1.7.2'))
			 let info = this.$store.state.d2admin.user.info
			 if(info.name == 'admin'){
				 let js = '超级管理员'
				 this.authKeys = ['超级管理员'].includes(js)
				 console.log(this.authKeys)
				 this.getTableData()
							/* let qx;
                      	Query({
							tablename:'菜单',
							columns:'二级菜单',
							field:'id',
							tj:true,
						})
						.then(resl => {
							 qx  = resl.map(function (v,){
								return v.二级菜单
							})
							console.log(qx);
						this.authKeys = qx
						this.getTableData()
						this.uname = info.name
						}).catch(err => {}) */
						}else{
				GetMenuTreeOnAuth({
                  username:info.name
				})
					.then(res => {			
                         let js = res.data.角色	
						 this.authKeys = ['超级管理员'].includes(js)	
						console.log(this.authKeys);
						this.getTableData()
						this.uname = info.name

					})
					.catch(err => {})
						}
			},
			getTableData() {
					let tjx		
				//if (this.authKeys.indexOf('消息通知') > -1) {
					this.loading = true
				if(this.searchFilter.name !='' && this.searchFilter.name != null){
					tjx =`用户名 LIKE '%${this.searchFilter.name}%'`	
					}else{
						tjx = true
					}
					Query({
							//pageSize: this.tablePage.pageSize,//每页条数 相当于layui的limit
							//currentPage: this.tablePage.currentPage, // 相当于layui的page
							//searchFilter: this.searchFilter  
							limit: this.tablePage.pageSize,
							page: this.tablePage.currentPage,
							tj:tjx,
							tablename:'用户',
							field:'id'
						})
						.then(res => {
							//this.tableData = res.data()
							console.log(res.data)
							this.tableData = res.data
							this.tablePage.totalResult = res.count
							this.loading = false
							
						})
						.catch(err => {
							// 异常情况
							this.loading = false
						})
				//}
			   
			},
			handleSearch() {
				this.tablePage.currentPage = 1 //注意要回来第一页
				this.getTableData()
			},
			handlePageChange({
				currentPage,
				pageSize
			}) {
				this.tablePage.currentPage = currentPage
				this.tablePage.pageSize = pageSize
				this.getTableData()
			},
			clearFilter() {
				let obj = this.searchFilter
				for (let key in obj) {
					this.searchFilter
					obj[key] = null
				}
			},

			exportDataEvent() {
				this.$refs.xTable1.exportData({
					type: 'csv'
				})
			},

			//用户删除
			deleteUsers() {
				let selectRecords = this.$refs.xTable1.getCheckboxRecords()
				let tempIDs = []
				for (let i = 0; i < selectRecords.length; i++) {
					let sr = selectRecords[i]
					tempIDs.push(sr.id)
					console.log(tempIDs)
				}
				if (tempIDs.length > 0) {
					this.$confirm('确定要永久删除这' + tempIDs.length + '行?', '提示', {
						confirmButtonText: '确定',
						cancelButtonText: '取消',
						type: 'warning'
					}).then(() => {
						this.fullscreenLoading = true
						Aud({
								//id: tempIDs.join(',')
						reqType:'delete',
						content:tempIDs,
						tablename:'用户'
							})
							.then(res => {
								this.fullscreenLoading = false
								this.getTableData()
								this.$message.success('删除成功')
							})
							.catch(err => {
								this.fullscreenLoading = false
							})
					}).catch(() => {});
				} else {
					this.$message.warning('请先勾选要删除的行')
				}
			},


			//权限复制
			showCopyDialog() {
				let selectRecords = this.$refs.xTable1.getCheckboxRecords()
				if (selectRecords.length > 0) {
					//this.authCopy.dialogVisible = true
                     Query({
                            tj:true,
							tablename:'用户',
							field:'id'  
					})
						.then(res => {
							console.log(res)
							//this.authCopy.userOptions =res.data
							this.authCopy.userOptions =res.data
							this.authCopy.dialogVisible = true
							//this.authCopy.userOptions = JSON.parse(res.data[0].功能权限)
							
						})
						.catch(err => {})
					

				} else {
					this.$message.warning('请先勾选要操作的行')
				}
			},
			handleCopyAuth() {
				let selectRecords = this.$refs.xTable1.getCheckboxRecords()
				let tempIDs = []
				for (let i = 0; i < selectRecords.length; i++) {
					let sr = selectRecords[i]
					tempIDs.push(sr.id)
				}
				let gns
				let gn = this.authCopy.form.selectUserID
				let gnarr2= selectRecords.map(function (v2) {
                    return  Object.assign({id:v2.id},{功能权限:gn});
                 })	
				 gnarr2.forEach(function (v,i) { 
					 if(v.id !='undefined'){                 
					gns += ` WHEN ${v.id} THEN '${v.功能权限}'`
					 }	
                    })
					console.log(gns)
					console.log(gns.replace('undefined',''));   										  			   
                 let sql = `UPDATE 用户 SET 功能权限 = CASE id  ${gns.replace('undefined','')} END WHERE id IN (${tempIDs.toString()})` 
				 console.log(sql)    
				if (tempIDs.length > 0) {
					this.$refs.authForm.validate((valid) => {
						if (valid) {
							this.$confirm('确定要把他的权限复制给勾选的用户？', '提示', {
								confirmButtonText: '确定',
								cancelButtonText: '取消',
								type: 'warning'
							}).then(() => {
								this.fullscreenLoading = true
                                Aud({
										//IDs: tempIDs.join(','),
										//selectUserID: this.authCopy.form.selectUserID
							    reqType:'updateshuzu',
					            content:sql, 
					            tablename:'用户' 
									})
									.then(res => {
										
										this.fullscreenLoading = false
										this.$message.success('权限批量复制成功!')
										this.closeCopyDialog()
									})
									.catch(err => {
										this.fullscreenLoading = false
									})
							
								/* this.fullscreenLoading = false

								this.closeCopyDialog() */
							}).catch(() => {})
						} else {
							return false;
						}
					})
				} else {
					this.$message.warning('请先勾选要操作的行')
				}
			},
			closeCopyDialog() {
				this.$refs.authForm.resetFields();
				this.authCopy.dialogVisible = false
			},

			formatterTF({
				cellValue
			}) {
				let item = this.TFList.find(item => item.value === cellValue)
				return item ? item.label : ''
			},

			//是否智能下拉---
			querySearch(queryString, cb) {
				let values = this.disables; //传入下拉列表数组
				let results = queryString ? values.filter(this.createFilter(queryString)) : values;
				// 调用 callback 返回建议列表的数据
				cb(results);
			},
			createFilter(queryString) {
				return (e) => {
					return (e.value.toLowerCase().indexOf(queryString.toLowerCase()) === 0);
				}
			},
			//是否智能下拉---


			goToAdd() {
				this.nowView = 2
				this.passID = ''
			},
			goToEdit(row) {
				console.log(row)
				this.nowView = 2
				this.passID = row.id
			},
			goBack() { //子组件对外触发的返回父事件
				this.nowView = 1
				this.getTableData()
			},
         dayin () {
		 const printStyle = `
        .title {
          text-align: center;
        }
        .my-list-row {
          display: inline-block;
          width: 100%;
        }
        .my-list-col {
          float: left;
          width: 33.33%;
          height: 28px;
          line-height: 28px;
        }
        .my-top,
        .my-bottom {
          font-size: 12px;
        }
        .my-top {
          margin-bottom: 5px;
        }
        .my-bottom {
          margin-top: 30px;
          text-align: right;
        }`
						  
              this.$refs.xTable1.print({   
				  sheetName: '打印表格',
                style: printStyle,            
				   beforePrintMethod: ({ content }) => {
					   let xsz = setter.getTime().split(' ');
              const topHtml = `
        <h1 class="title">出货单据</h1>
        <div class="my-top">
          <div class="my-list-row">
            <div class="my-list-col">商品名称：vxe-table</div>
            <div class="my-list-col">发货单号：X2665847132654</div>
            <div class="my-list-col">发货日期：${xsz[0]}</div>
          </div>
          <div class="my-list-row">
            <div class="my-list-col">收货姓名：小徐</div>
            <div class="my-list-col">收货地址：火星第七区18号001</div>
            <div class="my-list-col">联系电话：10086</div>
          </div>
        </div>
        `
        const bottomHtml = `
        <div class="my-bottom">
          <div class="my-list-row">
            <div class="my-list-col"></div>
            <div class="my-list-col">创建人：${this.uname}</div>
            <div class="my-list-col">创建日期：${xsz[0]}</div>
          </div>
        </div>
        `		
                  // 拦截打印之前，返回自定义的 html 内容
                  return topHtml + content + bottomHtml 
                } 
              })
            },
         printEvent1 () {
			 this.$print( this.$refs.print)
			 this.dialogTableVisible = false    
            },
		  ceshi(){
				Query({
							tablename:'菜单',
							columns:'二级菜单',
							field:'id',
							tj:true,
						})
						.then(resl => {
							console.log(resl)
							let xx  = resl.map(function (v,){
								return v.二级菜单
							})
							console.log(xx)
						})
		},
		},



	}
	
</script>

